select is((select count(*) from pg_constraint where conrelid in ('app.course_chapters'::regclass,'app.course_lessons'::regclass,'app.lesson_resources'::regclass,'app.course_releases'::regclass,'app.course_enrollments'::regclass,'app.lesson_progress'::regclass) and contype='f'),11::bigint,'Eleven explicit M2B foreign keys');
