select is((with f as (select conrelid,conkey from pg_constraint where contype='f' and connamespace='app'::regnamespace) select count(*) from f where not exists (select 1 from pg_index i where i.indrelid=f.conrelid and i.indisvalid and i.indisready and i.indpred is null and array(select k.attnum::smallint from unnest(i.indkey) with ordinality k(attnum,ord) where ord<=array_length(f.conkey,1) order by ord)=f.conkey)),0::bigint,'Whole schema full ordered FK coverage');
